// Server-only credentials generated by dev_platform.sh --debug. Never import
// this module into a client component or expose the token in page props.
export function localDebugToken(host: string | null, base = process.env.AGENT_PLATFORM_URL || ''): string | null {
  if (process.env.LILIES_LOCAL_DEBUG !== 'true') return null
  const token = process.env.LILIES_LOCAL_DEBUG_TOKEN || ''
  if (!/^[a-f0-9]{64}$/.test(token)) return null
  if (!host || !/^(127\.0\.0\.1|localhost|\[::1\])(:\d+)?$/i.test(host)) return null
  try {
    const url = new URL(base)
    if (url.protocol !== 'http:' || !['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname)
      || url.username || url.password) return null
  } catch { return null }
  return token
}
